      utmSource: "instagram",
      utmMedium: "social",
    }));
    assert.ok(r.ok);
  });

  it("returns error when repo save fails", async () => {
    repo.save.mockResolvedValueOnce({ ok: false, error: new Error("DB error") });
    const r = await uc.execute(makeInput());
    assert.ok(!r.ok);
    expect(r.error.message).toContain("Failed to save");
  });
});

